+    ctx.fillStyle = 'rgba(5,5,10,0.18)';
+    ctx.fillRect(0, 0, canvas.width, canvas.height);
+  }
+
+  const cx = canvas.width / 2, cy = canvas.height / 2;
+  ctx.save();
+  ctx.translate(cx, cy);
+  ctx.scale(camera.zoom, camera.zoom);
+  ctx.translate(-camera.x, -camera.y);
