+  }
+  ctx.restore();
+
+  frames++; fpsAccum += dt;
+  if (fpsAccum >= 0.5) {
+    document.getElementById('fps').textContent = Math.round(frames / fpsAccum);
+    document.getElementById('bcount').textContent = bodies.length;
+    frames = 0; fpsAccum = 0;
+  }
+
+  requestAnimationFrame(render);
+}
+requestAnimationFrame(render);
+</script>
+</body>
+</html>

