+      radius: 2, color: `hsl(${(200 + rng() * 160).toFixed(0)},80%,68%)`,
+    });
+  }
+  camera.zoom = 1.2;
+}
+function spawnBinary() {
+  bodies = [
+    { pos: { x: -120, y: 0 }, vel: { x: 0, y: -1.1 }, mass: 8000, radius: 10, color: '#ffd27a' },
+    { pos: { x: 120, y: 0 }, vel: { x: 0, y: 1.1 }, mass: 8000, radius: 10, color: '#7ab8ff' },
+  ];
+  const rng = makeRng(99);
+  for (let i = 0; i < Number(nRange.value); i++) {
+    const r = 180 + rng() * 260;
+    const ang = rng() * Math.PI * 2;
+    const speed = Math.sqrt((G * 16000) / r) * (0.8 + rng() * 0.3);
+    bodies.push({
+      pos: { x: Math.cos(ang) * r, y: Math.sin(ang) * r },
+      vel: { x: -Math.sin(ang) * speed, y: Math.cos(ang) * speed },
+      mass: 1 + rng() * 2, radius: 1.6, color: `hsl(${(30 + rng() * 60).toFixed(0)},90%,72%)`,
+    });
+  }
+  camera.zoom = 1.0;
+}
+
+nRange.addEventListener('input', () => { nVal.textContent = nRange.value; });
+speedRange.addEventListener('input', () => { speedMul = Number(speedRange.value); speedVal.textContent = speedMul.toFixed(1) + '×'; });
+thetaRange.addEventListener('input', () => { theta = Number(thetaRange.value); thetaVal.textContent = theta.toFixed(2); });
