+    const r = b.radius || Math.max(0.6, Math.cbrt(b.mass) * 0.4);
+    ctx.arc(b.pos.x, b.pos.y, r / camera.zoom > 0.4 ? r : 0.4, 0, Math.PI * 2);
+    ctx.fill();
+  }
+  ctx.restore();
+
+  frames++; fpsAccum += dt;
+  if (fpsAccum >= 0.5) {
+    document.getElementById('fps').textContent = Math.round(frames / fpsAccum);
+    document.getElementById('bcount').textContent = bodies.length;
+    frames = 0; fpsAccum = 0;
+  }
+
+  requestAnimationFrame(render);
+}
+requestAnimationFrame(render);
+</script>
+</body>
+</html>

